-- Fixed-project Management-only database executor and a separate Sandy migration
-- ledger. No existing provider migration contract/ledger is replaced. All new
-- operations are installed disabled and unverified pending real authorized tests.
BEGIN;
CREATE TABLE public.sandy_database_migration_ledger(
 version text PRIMARY KEY CHECK(version ~ '^[0-9]{14}_[a-z][a-z0-9_]{0,80}$'),
 name text NOT NULL,checksum text NOT NULL CHECK(checksum ~ '^[a-f0-9]{64}$'),
 state text NOT NULL CHECK(state='applied'),before_sha256 text NOT NULL,after_sha256 text NOT NULL,
 revision integer NOT NULL DEFAULT 1 CHECK(revision>=1),admission_id uuid NOT NULL REFERENCES public.sandy_api_execution_admissions(id),
 applied_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.sandy_database_migration_revisions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version text NOT NULL REFERENCES public.sandy_database_migration_ledger(version),
 revision integer NOT NULL,previous_checksum text NOT NULL,checksum text NOT NULL,observed_schema_sha256 text NOT NULL,
 reason text NOT NULL,admission_id uuid NOT NULL REFERENCES public.sandy_api_execution_admissions(id),
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(version,revision)
);
CREATE TABLE public.sandy_database_execution_receipts(
 admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),command_id uuid NOT NULL UNIQUE,
 operation text NOT NULL,input_sha256 text NOT NULL,result jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['sandy_database_migration_ledger','sandy_database_migration_revisions','sandy_database_execution_receipts'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;

CREATE FUNCTION public.sandy_api_database_schema_snapshot() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $snapshot$
 WITH raw AS(
  SELECT CASE c.relkind WHEN 'r' THEN 'table' WHEN 'p' THEN 'partitioned_table' WHEN 'v' THEN 'view' WHEN 'm' THEN 'materialized_view' WHEN 'i' THEN 'index' WHEN 'S' THEN 'sequence' END AS kind,
   n.nspname AS schema,c.relname AS name,
   jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
    'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'acl',a.attacl,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
    'constraints',(SELECT jsonb_agg(pg_get_constraintdef(k.oid) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),
    'view',CASE WHEN c.relkind IN('v','m') THEN pg_get_viewdef(c.oid,true) ELSE NULL END,
    'index',CASE WHEN c.relkind='i' THEN pg_get_indexdef(c.oid) ELSE NULL END,'sequence',(SELECT to_jsonb(seq)-'seqrelid' FROM pg_sequence seq WHERE seq.seqrelid=c.oid)) AS definition
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind IN('r','p','v','m','i','S')
  UNION ALL SELECT 'function',n.nspname,p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('source',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl)
   FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN('f','p')
  UNION ALL SELECT 'trigger',n.nspname,c.relname||'.'||t.tgname,to_jsonb(pg_get_triggerdef(t.oid))
   FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal
  UNION ALL SELECT 'policy',n.nspname,c.relname||'.'||p.polname,jsonb_build_object('command',p.polcmd,'permissive',p.polpermissive,'roles',p.polroles,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))
   FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
  UNION ALL SELECT 'enum',n.nspname,t.typname,(SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid)
   FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype='e'
  UNION ALL SELECT 'role','public',r.rolname,jsonb_build_object('superuser',r.rolsuper,'inherit',r.rolinherit,'create_role',r.rolcreaterole,'create_db',r.rolcreatedb,'login',r.rolcanlogin,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls,'connections',r.rolconnlimit) FROM pg_roles r
  UNION ALL SELECT 'role_membership','public',parent.rolname||'->'||member.rolname||'@'||grantor.rolname,jsonb_build_object('admin',a.admin_option,'inherit',a.inherit_option,'set',a.set_option,'grantor',grantor.rolname) FROM pg_auth_members a JOIN pg_roles parent ON parent.oid=a.roleid JOIN pg_roles member ON member.oid=a.member JOIN pg_roles grantor ON grantor.oid=a.grantor
  UNION ALL SELECT 'default_acl','public',owner.rolname||':'||d.defaclobjtype::text,to_jsonb(d.defaclacl) FROM pg_default_acl d JOIN pg_roles owner ON owner.oid=d.defaclrole JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='public'
  UNION ALL SELECT 'publication','public',p.pubname,jsonb_build_object('owner',pg_get_userbyid(p.pubowner),'all_tables',p.puballtables,'insert',p.pubinsert,'update',p.pubupdate,'delete',p.pubdelete,'truncate',p.pubtruncate,'tables',(SELECT jsonb_agg(jsonb_build_object('schema',t.schemaname,'table',t.tablename) ORDER BY t.schemaname,t.tablename) FROM pg_publication_tables t WHERE t.pubname=p.pubname)) FROM pg_publication p
 ), objects AS(SELECT kind,schema,name,encode(extensions.digest(definition::text,'sha256'),'hex') AS sha256 FROM raw),
 bounded AS(SELECT * FROM objects ORDER BY kind,schema,name LIMIT 2001),
 summary AS(SELECT coalesce(jsonb_agg(to_jsonb(b)-'row_number' ORDER BY kind,schema,name) FILTER(WHERE row_number<=2000),'[]'::jsonb) AS objects,count(*)>2000 AS truncated FROM(SELECT b.*,row_number() OVER(ORDER BY kind,schema,name) AS row_number FROM bounded b)b)
 SELECT jsonb_build_object('sha256',encode(extensions.digest(objects::text,'sha256'),'hex'),'objects',objects,'possibly_truncated',truncated) FROM summary
$snapshot$;

-- Check the exact canonical admission again at the actual database boundary.
-- This is not a customer JWT substitute: only the Management database role may
-- execute these functions, and the caller's API grant already binds a real owner.
CREATE FUNCTION public.sandy_api_database_authorize(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $authorize$
DECLARE a public.sandy_api_execution_admissions%ROWTYPE;r public.sandy_operation_registry%ROWTYPE;
 canonical text; actual_scope text;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR p->>'admission_id' IS NULL THEN RETURN jsonb_build_object('ok',false,'error','database_execution_context_invalid','http_status',403); END IF;
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=(p->>'admission_id')::uuid;
 IF NOT FOUND OR p->>'tenant_id' IS NOT NULL OR p->>'credential_id' IS NOT NULL OR a.state<>'consumed' OR a.expires_at<=clock_timestamp() OR a.credential_id IS NOT NULL OR a.tenant_id IS NOT NULL OR a.approval_id IS NULL
  OR a.actor_id IS DISTINCT FROM (p->>'actor_id')::uuid OR a.grant_id IS DISTINCT FROM (p->>'grant_id')::uuid
  OR a.request_id IS DISTINCT FROM (p->>'request_id')::uuid OR a.operation IS DISTINCT FROM p->>'operation'
  OR a.input_sha256 IS DISTINCT FROM p->>'input_sha256' OR a.contract_sha256 IS DISTINCT FROM p->>'contract_sha256'
  OR a.scope_sha256 IS DISTINCT FROM p->>'scope_sha256' OR NOT public.sandy_api_current_owner(a.actor_id) THEN
  RETURN jsonb_build_object('ok',false,'error','database_execution_grant_refused','http_status',403);
 END IF;
 canonical:=p->>'arguments_canonical';
 IF canonical IS NULL OR canonical::jsonb IS DISTINCT FROM p->'arguments'
  OR encode(extensions.digest(canonical,'sha256'),'hex') IS DISTINCT FROM a.input_sha256 THEN
  RETURN jsonb_build_object('ok',false,'error','database_argument_binding_mismatch','http_status',409);
 END IF;
 -- This exact constant uses Sandy's canonical JSON protocol, not jsonb spacing.
 actual_scope:=encode(extensions.digest('{"database":"postgres","project_ref":"zmqlyygzqoidkcwdysok","provider":"supabase","schema":"public"}','sha256'),'hex');
 SELECT * INTO r FROM public.sandy_operation_registry WHERE operation=a.operation;
 IF r.handler IS DISTINCT FROM 'sandy-database-operation-api' OR r.api_exposed IS DISTINCT FROM true OR r.verified IS DISTINCT FROM true
  OR r.error_contract->>'contract_sha256' IS DISTINCT FROM a.contract_sha256 OR r.error_contract->>'requires_approval' IS DISTINCT FROM 'true'
  OR r.error_contract->>'requires_grant' IS DISTINCT FROM 'true' OR a.scope_sha256 IS DISTINCT FROM actual_scope
  OR a.registry_revision_sha256 IS DISTINCT FROM public.sandy_api_registry_revision(a.operation) THEN
  RETURN jsonb_build_object('ok',false,'error','database_execution_contract_changed','http_status',409);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_api_mutation_approval_snapshots proof JOIN public.sandy_deployment_jobs job ON job.id=proof.job_id JOIN public.sandy_engineering_changes change ON change.id=proof.engineering_change_id WHERE proof.job_id=a.approval_id AND job.status='running' AND change.status='approved' AND proof.actor_id=a.actor_id AND proof.operation=a.operation AND proof.input_sha256=a.input_sha256 AND proof.contract_sha256=a.contract_sha256 AND proof.scope_sha256=a.scope_sha256 AND proof.maximum_declared_cost_units>=a.declared_cost_units AND proof.job_fingerprint_sha256=public.sandy_api_job_fingerprint(job)) THEN
  RETURN jsonb_build_object('ok',false,'error','database_scoped_approval_changed','http_status',409);
 END IF;
 RETURN jsonb_build_object('ok',true);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error','database_execution_context_invalid','http_status',403);
END $authorize$;

-- Public SELECTs may inspect plain stored relations only. A view/foreign table or
-- custom type could hide a side-effecting function behind apparently passive SQL.
CREATE FUNCTION public.sandy_api_database_passive_relations(p_statement jsonb) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $relations$
DECLARE ref jsonb; target oid; kind "char";
BEGIN
 FOR ref IN SELECT value FROM jsonb_array_elements(coalesce(p_statement->'passive_relations','[]'::jsonb)) LOOP
  IF ref->>'schema'='pg_catalog' AND ref->>'name' IN('pg_namespace','pg_database','pg_roles','pg_locks','pg_stat_database') OR ref->>'schema'='information_schema' AND ref->>'name' IN('schemata','tables','table_constraints','key_column_usage','referential_constraints','constraint_column_usage') THEN CONTINUE; END IF;
  IF ref->>'schema' IS DISTINCT FROM 'public' THEN RAISE EXCEPTION 'database_passive_relation_required'; END IF;
  IF ref->>'name' ~ '(?:^|_)(?:secret|secrets|credential|credentials|token|tokens|password|passwords|api_key|apikey|signing_key)(?:_|$)'
   OR ref->>'name' ~ '^sandy_' AND ref->>'name' NOT IN('sandy_tasks','sandy_calendar_events','sandy_universal_files','sandy_agenda_companies','sandy_agenda_categories')
   OR ref->>'name' IN('email_customers','email_customer_addresses') THEN RAISE EXCEPTION 'database_protected_object_refused'; END IF;
  SELECT c.oid,c.relkind INTO target,kind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ref->>'name';
  IF target IS NOT NULL AND EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped AND a.attname ~* '(password|passwd|secret|credential|access.?token|refresh.?token|private.?key|api.?key|signing.?key|authorization|cookie|connection.?string|encrypted.?value|subconninfo|rolpassword|srvoptions|umoptions|fdwoptions)') THEN
   RAISE EXCEPTION 'database_sensitive_source_refused';
  END IF;
  IF target IS NULL OR kind<>'r' OR EXISTS(
   SELECT 1 FROM pg_attribute a JOIN pg_type t ON t.oid=a.atttypid JOIN pg_namespace n ON n.oid=t.typnamespace
   WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped AND n.nspname<>'pg_catalog') THEN
   RAISE EXCEPTION 'database_passive_relation_required';
  END IF;
 END LOOP;
END $relations$;


-- Volatile writes lock each exact source immediately before its guard. A prior
-- statement may have created it; no future table is locked before CREATE.
CREATE FUNCTION public.sandy_api_database_lock_relations(p_statement jsonb) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $locks$
DECLARE ref jsonb;
BEGIN
 FOR ref IN SELECT item.value FROM jsonb_array_elements(coalesce(p_statement->'passive_relations','[]'::jsonb)) item(value) ORDER BY item.value->>'schema',item.value->>'name' LOOP
  IF ref->>'schema'='public' THEN
   IF ref->>'name' IS NULL OR ref->>'name' !~ '^[a-z_][a-z0-9_]{0,62}$' THEN RAISE EXCEPTION 'database_passive_relation_required'; END IF;
   EXECUTE format('LOCK TABLE public.%I IN ACCESS SHARE MODE',ref->>'name');
  END IF;
 END LOOP;
 PERFORM public.sandy_api_database_passive_relations(p_statement);
END $locks$;

-- Fail closed on sensitive output names even under SELECT */RETURNING * and
-- nested row JSON. Credentials are handled by custody operations, never logs.
CREATE FUNCTION public.sandy_api_database_result_safe(p jsonb,p_depth integer DEFAULT 0) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $safe$
DECLARE entry record; nested_value jsonb;
BEGIN
 IF p_depth>40 THEN RETURN false; END IF;
 IF jsonb_typeof(p)='object' THEN
  FOR entry IN SELECT item.key,item.value FROM jsonb_each(p) item LOOP
   IF entry.key ~* '(password|passwd|secret|credential|access.?token|refresh.?token|private.?key|api.?key|signing.?key|authorization|cookie|connection.?string|encrypted.?value|prosrc|probin|proconfig|subconninfo|rolpassword|srvoptions|umoptions|fdwoptions)'
    OR NOT public.sandy_api_database_result_safe(entry.value,p_depth+1) THEN RETURN false;END IF;
  END LOOP;
 ELSIF jsonb_typeof(p)='array' THEN
  FOR nested_value IN SELECT item.value FROM jsonb_array_elements(p) item(value) LOOP IF NOT public.sandy_api_database_result_safe(nested_value,p_depth+1) THEN RETURN false; END IF; END LOOP;
 END IF;
 RETURN true;
END $safe$;

CREATE FUNCTION public.sandy_api_database_preflight(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $preflight$
DECLARE permission jsonb; dependency text; metadata jsonb;
BEGIN
 IF current_setting('transaction_read_only')<>'on' THEN RETURN jsonb_build_object('ok',false,'error','database_read_only_transport_required','http_status',403); END IF;
 permission:=public.sandy_api_database_authorize(p); IF permission->>'ok'<>'true' THEN RETURN permission; END IF;
 metadata:=p->'plan'->'metadata';dependency:=metadata->>'required_extension';
 IF dependency IS NOT NULL AND NOT EXISTS(SELECT 1 FROM pg_extension WHERE extname=dependency) THEN
  RETURN jsonb_build_object('ok',false,'error','database_required_extension_unavailable','http_status',424);
 END IF;
 RETURN jsonb_build_object('ok',true);
END $preflight$;

CREATE FUNCTION public.sandy_api_database_read(p jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $read$
DECLARE permission jsonb; statement jsonb; current_row record; row_json json; rows jsonb; statements jsonb:='[]';
 row_limit integer; truncated boolean; any_truncated boolean:=false; duplicate_columns boolean;
BEGIN
 permission:=public.sandy_api_database_preflight(p); IF permission->>'ok'<>'true' THEN RETURN permission; END IF;
 row_limit:=(p->'plan'->>'result_limit')::integer;
 IF row_limit NOT BETWEEN 1 AND 1000 OR jsonb_array_length(p->'plan'->'statements')>100 THEN RAISE EXCEPTION 'database_plan_invalid'; END IF;
 FOR statement IN SELECT value FROM jsonb_array_elements(p->'plan'->'statements') LOOP
  IF statement->>'mode'<>'query' THEN RAISE EXCEPTION 'database_read_only_select_required'; END IF;
  PERFORM public.sandy_api_database_passive_relations(statement);
  rows:='[]';truncated:=false;
  FOR current_row IN EXECUTE statement->>'sql' USING statement->'parameters' LOOP
   IF jsonb_array_length(rows)>=row_limit THEN truncated:=true;EXIT;END IF;
   row_json:=row_to_json(current_row);
   SELECT count(*)<>count(DISTINCT key) INTO duplicate_columns FROM json_each(row_json);
   IF duplicate_columns THEN RAISE EXCEPTION 'database_duplicate_output_columns'; END IF;
   IF NOT public.sandy_api_database_result_safe(row_json::jsonb) THEN RAISE EXCEPTION 'database_sensitive_result_refused'; END IF;
   rows:=rows||jsonb_build_array(row_json::jsonb);
   IF octet_length(rows::text)>1024*1024 THEN RAISE EXCEPTION 'database_result_size_limit'; END IF;
  END LOOP;
  statements:=statements||jsonb_build_array(jsonb_build_object('row_count',jsonb_array_length(rows),'rows',rows,'possibly_truncated',truncated));
  IF octet_length(statements::text)>1024*1024 THEN RAISE EXCEPTION 'database_result_size_limit'; END IF;
  any_truncated:=any_truncated OR truncated;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'contract_version','1.0.0','operation',p->>'operation','project_ref','zmqlyygzqoidkcwdysok',
  'read_only',true,'transactional',true,'mutation_committed',false,'verification_passed',false,'command_id',NULL,
  'statements',statements,'result_limit',row_limit,'possibly_truncated',any_truncated);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('ok',false,'error',CASE WHEN SQLERRM IN('database_passive_relation_required','database_protected_object_refused','database_index_parent_unavailable','database_sensitive_source_refused','database_duplicate_output_columns','database_result_size_limit','database_sensitive_result_refused') THEN SQLERRM ELSE 'database_read_failed' END,'http_status',400);
END $read$;

CREATE FUNCTION public.sandy_api_database_write(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $write$
DECLARE permission jsonb; admission uuid; prior public.sandy_database_execution_receipts%ROWTYPE;
 ledger public.sandy_database_migration_ledger%ROWTYPE; migration jsonb; repair jsonb; statement jsonb; test jsonb;
 result jsonb; rows jsonb; statements jsonb:='[]'; snapshot jsonb; before_sha text; after_sha text; command uuid:=gen_random_uuid();
 row_limit integer; affected_limit integer; count_rows bigint;total_affected bigint:=0; any_truncated boolean:=false; reused boolean:=false;
 sql text; body text; current_row record; actual_rows jsonb; row_json json; duplicate_columns boolean; message text; routine text; routine_sha text; index_name text; parent_name text;
BEGIN
 permission:=public.sandy_api_database_authorize(p);IF permission->>'ok'<>'true' THEN RETURN permission;END IF;
 admission:=(p->>'admission_id')::uuid;
 -- Serialize duplicate delivery at the durable command boundary, not merely in
 -- Edge memory. The original receipt returns without repeating triggers/DDL.
 PERFORM id FROM public.sandy_api_execution_admissions WHERE id=admission FOR UPDATE;
 SELECT * INTO prior FROM public.sandy_database_execution_receipts WHERE admission_id=admission;
 IF FOUND THEN
  IF prior.operation IS DISTINCT FROM p->>'operation' OR prior.input_sha256 IS DISTINCT FROM p->>'input_sha256' THEN RAISE EXCEPTION 'database_receipt_conflict'; END IF;
  RETURN prior.result||jsonb_build_object('receipt_reused',true);
 END IF;
 IF current_setting('transaction_read_only')='on' THEN RAISE EXCEPTION 'database_write_transport_required'; END IF;
 PERFORM set_config('standard_conforming_strings','on',true);
 PERFORM set_config('lock_timeout','3s',true);
 row_limit:=(p->'plan'->>'result_limit')::integer;affected_limit:=(p->'plan'->>'max_affected_rows')::integer;
 IF row_limit NOT BETWEEN 1 AND 1000 OR affected_limit NOT BETWEEN 1 AND 1000 OR p->'plan'->>'mode'<>'transaction'
  OR jsonb_array_length(p->'plan'->'statements')>100 OR jsonb_array_length(p->'plan'->'verifications') NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'database_plan_invalid'; END IF;
 migration:=p->'plan'->'migration';repair:=p->'plan'->'repair';
 IF migration IS NOT NULL OR repair IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('sandy_database_migration_ledger',0));
  snapshot:=public.sandy_api_database_schema_snapshot();
  IF snapshot->>'possibly_truncated'='true' THEN RAISE EXCEPTION 'database_schema_snapshot_incomplete'; END IF;
  before_sha:=snapshot->>'sha256';
  IF migration IS NOT NULL THEN
   SELECT * INTO ledger FROM public.sandy_database_migration_ledger WHERE version=migration->>'version' FOR UPDATE;
   IF FOUND THEN
    IF ledger.checksum<>migration->>'checksum' THEN RAISE EXCEPTION 'database_migration_checksum_conflict'; END IF;
    reused:=true;
   ELSIF before_sha IS DISTINCT FROM migration->>'expected_before_sha256' THEN RAISE EXCEPTION 'database_schema_drift'; END IF;
  ELSE
   SELECT * INTO ledger FROM public.sandy_database_migration_ledger WHERE version=repair->>'version' FOR UPDATE;
   IF NOT FOUND OR ledger.checksum IS DISTINCT FROM repair->>'expected_checksum' OR before_sha IS DISTINCT FROM repair->>'expected_schema_sha256' THEN RAISE EXCEPTION 'database_migration_repair_conflict'; END IF;
  END IF;
 END IF;
 -- The caller supplies the exact safe parsed definition. Under the fixed
 -- pg_catalog-only path, deparsing exposes noncatalogue operators/functions.
 -- The Management wrapper holds AccessShare on target+sources against DDL.
 IF p->'plan'->'metadata'->'reviewed_materialized_view' IS NOT NULL THEN
  PERFORM public.sandy_api_database_lock_relations(p->'plan'->'statements'->0);
  -- PostgreSQL forbids LOCK TABLE on a materialized view. WITH NO DATA executes
  -- no definition and obtains its transaction lock; every failure below rolls
  -- the cleared storage back before returning an error or touching a source.
  IF NOT reused THEN EXECUTE format('REFRESH MATERIALIZED VIEW public.%I WITH NO DATA',p->'plan'->'metadata'->'reviewed_materialized_view'->>'name'); END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='public' AND c.relkind='m' AND c.relname=p->'plan'->'metadata'->'reviewed_materialized_view'->>'name'
    AND pg_get_viewdef(c.oid,false)=p->'plan'->'metadata'->'reviewed_materialized_view'->>'definition_sql')
   THEN RAISE EXCEPTION 'database_materialized_definition_changed'; END IF;
 END IF;
 routine:=p->'plan'->'metadata'->>'reviewed_trigger_function';
 IF routine IS NOT NULL THEN
  SELECT encode(extensions.digest(pg_get_functiondef(f.oid),'sha256'),'hex') INTO routine_sha FROM pg_proc f JOIN pg_namespace n ON n.oid=f.pronamespace WHERE n.nspname='public' AND f.proname=routine AND f.pronargs=0 AND f.prorettype='pg_catalog.trigger'::regtype;
  IF routine_sha IS NULL OR routine_sha IS DISTINCT FROM p->'plan'->'metadata'->>'reviewed_trigger_sha256' THEN RAISE EXCEPTION 'database_reviewed_trigger_changed'; END IF;
 END IF;
 IF NOT reused THEN
  FOR statement IN SELECT value FROM jsonb_array_elements(p->'plan'->'statements') LOOP
   sql:=statement->>'sql';
   IF statement->>'mode'='dml' THEN
    PERFORM public.sandy_api_database_lock_relations(statement);
    body:=format(E'WITH effect AS (%s\n), records AS(SELECT row_to_json(e) AS data,row_number() OVER() AS n FROM effect e) SELECT jsonb_build_object(''row_count'',count(*),''rows'',coalesce(jsonb_agg(data::jsonb) FILTER(WHERE n<=%s),''[]''::jsonb),''possibly_truncated'',count(*)>%s,''duplicate_columns'',coalesce(bool_or((SELECT count(*)<>count(DISTINCT key) FROM json_each(data))),false)) FROM records',sql,row_limit,row_limit);
    EXECUTE body INTO result USING statement->'parameters';
    count_rows:=(result->>'row_count')::bigint;
    total_affected:=total_affected+count_rows;
    IF total_affected>affected_limit THEN RAISE EXCEPTION 'database_affected_row_limit'; END IF;
    IF result->>'duplicate_columns'='true' THEN RAISE EXCEPTION 'database_duplicate_output_columns'; END IF;
    result:=result-'duplicate_columns';
   ELSIF statement->>'mode'='command' THEN
    FOR index_name IN SELECT jsonb_array_elements_text(coalesce(statement->'index_targets','[]'::jsonb)) LOOP
     SELECT parent.relname INTO parent_name FROM pg_class idx JOIN pg_namespace n ON n.oid=idx.relnamespace JOIN pg_index ix ON ix.indexrelid=idx.oid JOIN pg_class parent ON parent.oid=ix.indrelid JOIN pg_namespace pn ON pn.oid=parent.relnamespace WHERE n.nspname='public' AND idx.relname=index_name AND pn.nspname='public';
