    END LOOP;
    PERFORM public.sandy_api_database_lock_relations(statement);
    EXECUTE sql USING statement->'parameters';GET DIAGNOSTICS count_rows=ROW_COUNT;
    result:=jsonb_build_object('row_count',count_rows,'rows','[]'::jsonb,'possibly_truncated',false);
   ELSIF statement->>'mode'='query' THEN
    PERFORM public.sandy_api_database_lock_relations(statement);
    rows:='[]';count_rows:=0;
    FOR current_row IN EXECUTE sql USING statement->'parameters' LOOP
     count_rows:=count_rows+1;
     row_json:=row_to_json(current_row);
     SELECT count(*)<>count(DISTINCT key) INTO duplicate_columns FROM json_each(row_json);
     IF duplicate_columns THEN RAISE EXCEPTION 'database_duplicate_output_columns'; END IF;
     IF count_rows<=row_limit THEN rows:=rows||jsonb_build_array(row_json::jsonb); END IF;
     IF count_rows>row_limit THEN EXIT; END IF;
    END LOOP;
    result:=jsonb_build_object('row_count',least(count_rows,row_limit),'rows',rows,'possibly_truncated',count_rows>row_limit);
   ELSE RAISE EXCEPTION 'database_plan_invalid'; END IF;
   IF NOT public.sandy_api_database_result_safe(result) THEN RAISE EXCEPTION 'database_sensitive_result_refused'; END IF;
   IF octet_length(result::text)>1024*1024 THEN RAISE EXCEPTION 'database_result_size_limit'; END IF;
