  END IF;
 END IF;
 result:=jsonb_build_object('ok',true,'contract_version','1.0.0','operation',p->>'operation','project_ref','zmqlyygzqoidkcwdysok',
  'read_only',false,'transactional',true,'mutation_committed',true,'verification_passed',true,'command_id',command,
  'statements',statements,'result_limit',row_limit,'possibly_truncated',any_truncated,'receipt_reused',false);
 IF migration IS NOT NULL OR repair IS NOT NULL THEN result:=result||jsonb_build_object('migration',jsonb_build_object('version',ledger.version,'checksum',ledger.checksum,'before_sha256',ledger.before_sha256,'after_sha256',ledger.after_sha256,'revision',ledger.revision,'reused',reused,'repaired',repair IS NOT NULL));END IF;
